1	const PROCESSING_FEE = 5;
2	
3	export type Item = {
4	  type: string;
5	};
6	
7	export type Scenario = {
8	  customer: { yearsWithMHPCO: number };
9	  steps: { op: string; items: Item[] }[];
10	};
11	
12	export type ScenarioResult = {
13	  results: { premium: number }[];
14	};
15	
16	const BASE_PREMIUMS: Record<string, number> = {
17	  sword: 100,
18	  amulet: 60,
19	};
20	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
21	
22	const percentOf = (amount: number, percent: number): number =>
23	  (amount * percent) / 100;
24	
25	const roundInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
26	
27	const quotePremium = (items: Item[]): number => {
28	  const basePremium = items.reduce(
29	    (sum, item) => sum + BASE_PREMIUMS[item.type],
30	    0,
31	  );
32	  const withFirstInsuranceSurcharge =
33	    basePremium + percentOf(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT);
34	  return roundInMHPCOsFavour(withFirstInsuranceSurcharge + PROCESSING_FEE);
35	};
36	
37	export const runScenario = (scenario: Scenario): ScenarioResult => ({
38	  results: scenario.steps.map((step) => ({
39	    premium: quotePremium(step.items),
40	  })),
41	});
